206	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
207	        this.possibleDuplicateOf = possibleDuplicateOf;
208	    }
209	
210	    /**
211	     * The owner's membership level, a number from 1 to 3 derived at read time from stored fields.
212	     * Starts at 1; add 1 when an email is present; add 1 when {@link #getNamesakeCount() namesakeCount}
213	     * is 0; capped at 3 (level 4 is reserved for tenure).
214	     */
215	    @Transient
216	    public Integer getMembershipLevel() {
217	        int level = 1;
218	        boolean hasEmail = this.email != null && !this.email.isBlank();
219	        if (hasEmail) {
220	            level++;
221	        }
222	        if (this.namesakeCount != null && this.namesakeCount == 0) {
223	            level++;
224	        }
225	        return Math.min(level, 3);
226	    }
227	
228	    /**
229	     * A single Luhn check digit (0-9) computed at read time over the digits contained in the
230	     * {@link #getCustomerCode() customerCode} (non-digit characters such as the '-' separators are
231	     * ignored). {@code null} when the owner has no customerCode.
232	     */
233	    @Transient
234	    public Integer getCheckDigit() {
235	        if (this.customerCode == null) {
236	            return null;
237	        }
238	        int sum = 0;
239	        boolean dbl = true;
240	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
241	            char c = this.customerCode.charAt(i);
242	            if (c < '0' || c > '9') {
243	                continue;
244	            }
245	            int d = c - '0';
246	            if (dbl) {
247	                d *= 2;
248	                if (d > 9) {
249	                    d -= 9;
250	                }
251	            }
252	            sum += d;
253	            dbl = !dbl;
254	        }
255	        return (10 - (sum % 10)) % 10;
256	    }
257	
258	    /**
259	     * The owner's region, derived at read time. The {@link #getPostcode() postcode} is preferred:
260	     * a 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
261	     * QLD 4000-4099) yields that region, which disambiguates cities that share a name. Only when the
262	     * postcode is absent (or in no known range) does it fall back to the fixed city-to-region table
263	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}). Any unresolved value
264	     * yields {@code 'UNKNOWN'}.
265	     */
266	    @Transient
267	    public String getLocality() {
268	        String byPostcode = regionForPostcode(this.postcode);
269	        if (byPostcode != null) {
270	            return byPostcode;
271	        }
272	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
273	    }
274	
275	    /** The region whose range contains {@code postcode}, or {@code null} when absent/out of range. */
276	    private static String regionForPostcode(String postcode) {
277	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
278	            return null;
279	        }
280	        int value = Integer.parseInt(postcode);
281	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
282	            int[] range = entry.getValue();
283	            if (value >= range[0] && value <= range[1]) {
284	                return entry.getKey();
285	            }
286	        }
287	        return null;
288	    }
289	
290	    /**
291	     * The owner's preferred contact channel, derived at read time: {@code 'EMAIL'} when an
292	     * {@link #getEmail() email} is present, otherwise {@code 'PHONE'}.
293	     */
294	    @Transient
295	    public String getContactPreference() {
296	        boolean hasEmail = this.email != null && !this.email.isBlank();
297	        return hasEmail ? "EMAIL" : "PHONE";
298	    }
299	
300	    /**
301	     * The owner's age band, derived at read time from {@link #getBirthDate() birthDate} measured
302	     * against the {@link #getRegistrationDate() registrationDate}: {@code 'MINOR'} when the owner is
303	     * under 18 at registration, {@code 'ADULT'} from 18 to 64, {@code 'SENIOR'} at 65 or over.
304	     * {@code null} when the owner has no birthDate (or no registrationDate to measure against).
305	     */
306	    @Transient
307	    public String getAgeBand() {
308	        if (this.birthDate == null || this.registrationDate == null) {
309	            return null;
310	        }
311	        int years = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
312	        if (years < 18) {
313	            return "MINOR";
314	        }
315	        if (years < 65) {
316	            return "ADULT";
317	        }
318	        return "SENIOR";
319	    }
320	
321	    /**
322	     * The single derived duplicate-detection key, {@code normalizedTelephone|email|householdId}
323	     * (the normalized telephone, the email or empty when absent, and the householdId or empty when
324	     * the owner has a unique household). All duplicate detection is expressed through this one key:
325	     * a create whose WHOLE identityKey equals an existing owner's is a duplicate. Because the
326	     * telephone is part of the key, two members of the same household with different telephones have
327	     * different identityKeys and are both allowed.
328	     */
329	    @Transient
330	    public String getIdentityKey() {
331	        String tel = this.telephone == null ? "" : this.telephone;
332	        String mail = (this.email == null || this.email.isBlank()) ? "" : this.email;
333	        String household = (this.householdId == null || this.householdId.isBlank()) ? "" : this.householdId;
334	        return tel + "|" + mail + "|" + household;
335	    }
336	
337	    /** City -> canonical region for {@link #getLocality()}. Any other city is 'UNKNOWN'. */
338	    private static final Map<String, String> CITY_REGION =
